# Français — 6e AS, séries Lettres (A et O) (IPN, 2025). Contenu tiré du manuel uniquement.
# Chaque texte du manuel = une leçon : le texte (image du manuel), compréhension (questions/réponses), production.
# Les textes communs avec le manuel 6e C/D reprennent les leçons de FR_6CD (mêmes questions), avec les pages de ce manuel.
import copy, importlib.util, os

BOOK = "FR_6AO"

_spec = importlib.util.spec_from_file_location("FR_6CD_src", os.path.join(os.path.dirname(os.path.abspath(__file__)), "FR_6CD.py"))
_cd = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(_cd)


def F(page, y0, y1, x0=0.06, x1=0.94, cap=""):
    return {"page": page, "rect": [x0, y0, x1, y1], "caption": cap}


def S(h, lines=None, table=None):
    d = {"h": h, "lines": lines or []}
    if table:
        d["table"] = table
    return d


def _figs(figs):
    return [{"h": "Le texte" + (f" ({i+1}/{len(figs)})" if len(figs) > 1 else ""), "lines": [], "fig": f} for i, f in enumerate(figs)]


def T(title, pages, figs, objectives, intro, summary, points, qa, production, extra=None, apps=()):
    board = _figs(figs)
    board.append({"h": "Compréhension", "lines": [], "table": [["Question", "Réponse"]] + [list(x) for x in qa]})
    if extra:
        board += extra
    board.append({"h": "Production", "lines": production})
    q, a = qa[0]
    return {"title": title, "match": [title], "pages": pages, "objectives": objectives, "intro": intro,
            "summary": summary, "points": points, "application": {"q": q, "a": a},
            "applications": [{"q": x, "a": y} for x, y in apps], "board": board}


def X(title, pages, objectives, intro, summary, points, board, app, apps=()):
    return {"title": title, "match": [title], "pages": pages, "objectives": objectives, "intro": intro,
            "summary": summary, "points": points, "application": {"q": app[0], "a": app[1]},
            "applications": [{"q": x, "a": y} for x, y in apps], "board": board}


def R(key, title, pages, figs, extra=None):
    """Reprend une leçon de FR_6CD (texte identique) avec les pages et les images de ce manuel."""
    src = next(l for l in _cd.LESSONS if key in l["title"])
    l = copy.deepcopy(src)
    l["title"] = title
    l["match"] = [title]
    l["pages"] = pages
    rest = [b for b in l["board"] if "fig" not in b]
    if extra:
        rest = rest[:-1] + extra + rest[-1:]
    l["board"] = _figs(figs) + rest
    return l


